function DRIFT_MONITOR(trajectory, k):
    base <- CONSERVED(trajectory[0], k)        # (L_z, E, A_x, A_y)
    drift <- (0, 0, 0, 0)
    for state in trajectory:
        cur <- CONSERVED(state, k)
        for i in {L_z, E, A_x, A_y}:
            drift[i] <- max(drift[i], |cur[i] - base[i]|)
    return drift

function CONSERVED(state=(x,y,vx,vy), k):
    r   <- sqrt(x^2 + y^2)
    L_z <- x*vy - y*vx
    E   <- 0.5*(vx^2 + vy^2) - k/r
    A_x <- L_z*vy - k*x/r
    A_y <- -L_z*vx - k*y/r
    return (L_z, E, A_x, A_y)

function DISCRIMINATE_FORCE_LAW(s0, k, dt, steps, powers):
    results <- []
    for p in powers:
        traj <- VELOCITY_VERLET(s0, k, dt, steps, p)
        results.append((p, LRL_DRIFT(traj, k)))
    return results        # minimized at p = 2

function VELOCITY_VERLET(s0, k, dt, steps, p):
    (x,y,vx,vy) <- s0;  (ax,ay) <- FORCE(x,y,k,p)
    for _ in 1..steps:
        vx += dt/2*ax; vy += dt/2*ay
